<script lang="ts">
  import { formatPaisa } from '$lib/format';
  import { invalidateAll } from '$app/navigation';
  import { onMount } from 'svelte';
  let { data } = $props();
  let mine = $derived(data.balances.find(b => b.userId === data.currentUserId)?.amountPaisa ?? 0);
  let names = $derived(new Map(data.roommates.map(u => [u.id, u.name])));
  const icons: Record<string,string> = { chai: '☕', mess: '♨', delivery: '↗', groceries: '◈', bills: '▤', other: '○' };
  onMount(() => { const refresh = () => { if (document.visibilityState === 'visible') void invalidateAll(); }; const timer = setInterval(refresh, 15000); document.addEventListener('visibilitychange', refresh); return () => { clearInterval(timer); document.removeEventListener('visibilitychange', refresh); }; });
</script>
<div class="page-heading"><div><p class="eyebrow">Your shared space</p><h1>A little less keeping count.</h1><p class="muted">Here's where your room stands today.</p></div><a class="button" href="/expense/new">+ Add expense</a></div>
<section class="overview-grid"><div class="balance-card"><div class="balance-top"><span>Your balance</span><span class="balance-symbol">↗</span></div><h2>{formatPaisa(Math.abs(mine))}</h2><p>{mine < 0 ? 'You owe the room' : mine > 0 ? 'The room owes you' : 'All settled. Enjoy the peace.'}</p><div class="balance-footer"><span>Confirmed activity only</span><a href="/settle">Settle up →</a></div></div><a class="quick-card" href="/expenses"><span class="section-icon">▤</span><h2>Every rupee, accounted for.</h2><p class="muted">Explore expenses, custom splits and your charges.</p><span class="quick-link">Browse expenses →</span></a><a class="quick-card" href="/reviews"><span class="section-icon">⚖</span><h2>Keep it fair.</h2><p class="muted">Review rejected shares and reported expenses together.</p><span class="quick-link">Open room reviews →</span></a></section>
{#if data.roommates.some(u => u.isLocked)}<a class="notice banner" href="/admin/locked">🥤 Cold drink confirmation needed. Review locked roommates →</a>{/if}
{#each data.pendingApprovals as id}<a class="notice banner" href="/expense/{id}">You have a charge waiting for your approval. Review it →</a>{/each}
<div class="activity-grid"><section class="card"><div class="section-heading"><h2>Room balances</h2><span class="badge">{data.balances.length} members</span></div><div class="members">{#each data.balances as balance}<a class="member" href={balance.userId === data.currentUserId ? '/settle' : `/ledger/${balance.userId}`}><span class="member-avatar">{balance.name.slice(0,1)}</span><span class="member-name"><strong>{balance.name}</strong><small>{balance.userId === data.currentUserId ? 'You' : 'Roommate'}</small></span><span class="member-amount" class:negative={balance.amountPaisa < 0}><strong>{formatPaisa(Math.abs(balance.amountPaisa))}</strong><small>{balance.amountPaisa < 0 ? 'owes' : balance.amountPaisa > 0 ? 'gets back' : 'settled'}</small></span></a>{/each}</div></section>
<section class="card"><div class="section-heading"><h2>Recent activity</h2><a class="all-link" href="/expenses">View all ↗</a></div>{#each data.recent as expense}<a class="expense" href="/expense/{expense.id}"><span class="expense-icon">{icons[expense.category] ?? '○'}</span><span class="expense-label"><strong>{expense.description || expense.category}</strong><small>{names.get(expense.paidBy)} paid · {expense.status === 'voided' ? 'cancelled' : expense.status.replaceAll('_',' ')}</small></span><strong class="expense-amount">{formatPaisa(expense.amountPaisa)}</strong></a>{:else}<div class="empty"><span class="section-icon">+</span><h2>The first bill starts here.</h2><p class="muted">Tea, groceries, or a late-night order—add an expense to get started.</p></div>{/each}</section></div>
